<template>
  <section class="page">
    <header class="page__header"><div><h1 class="page__title">车辆进出记录</h1><p class="page__desc">查看车辆通行记录与放行信息</p></div><button class="button button--soft button--sm" type="button" @click="exportRecords"><span class="material-icons-outlined">download</span>导出</button></header>
    <section class="card">
      <div class="card__body card__body--filters"><div class="toolbar"><input v-model.trim="filters.keyword" class="input" type="search" placeholder="搜索车牌 / 车主 / 部门" @keyup.enter="search"><select v-model="filters.direction" class="select" aria-label="通行方向"><option value="">全部方向</option><option value="进">进</option><option value="出">出</option></select><select v-model="filters.gate" class="select" aria-label="通道"><option value="">全部通道</option><option v-for="gate in gates" :key="gate" :value="gate">{{ gate }}</option></select><select v-model="filters.passType" class="select" aria-label="放行类型"><option value="">全部放行类型</option><option v-for="passType in passTypes" :key="passType" :value="passType">{{ passType }}</option></select><div class="toolbar__right"><button class="button button--soft button--sm" type="button" @click="search"><span class="material-icons-outlined">search</span>搜索</button><button class="button button--ghost button--sm" type="button" @click="resetFilters"><span class="material-icons-outlined">restart_alt</span>重置</button></div></div></div>
      <div v-if="loading" class="state">正在加载车辆进出记录...</div><div v-else-if="errorMessage" class="state state--error">{{ errorMessage }}</div><div v-else class="table-wrap"><table class="table"><thead><tr><th>进/出图片</th><th>车牌号码</th><th>车主名称</th><th>方向</th><th>进/出时间</th><th>进出场地点</th><th>车辆类型</th><th>放行类型</th><th>记录状态</th><th class="actions-cell">操作</th></tr></thead><tbody><tr v-for="record in pagedRecords" :key="record.id"><td><img v-if="record.photo" :src="record.photo" class="record-car" :alt="record.plate || '车辆'" loading="lazy"><span v-else class="record-photo" :class="record.direction === '进' ? 'record-photo--in' : 'record-photo--out'"><span class="material-icons-outlined">directions_car</span></span></td><td class="plate">{{ record.plate || "-" }}</td><td>{{ record.owner || "-" }}</td><td><span class="tag" :class="record.direction === '进' ? 'tag--blue' : 'tag--gray'">{{ record.direction }}</span></td><td class="text-sub nowrap">{{ record.time }}</td><td>{{ record.gate || "-" }}</td><td>{{ record.vehicleType || "-" }}</td><td><span class="tag" :class="passClass(record.passType)">{{ record.passType || "-" }}</span></td><td class="text-sub remark-cell">{{ record.status || "-" }}</td><td class="actions-cell"><button class="detail-action" type="button" :aria-label="`查看${record.plate || '车辆'}详情`" @click="openDetails(record)"><span class="material-icons-outlined">visibility</span>查看详情</button></td></tr><tr v-if="pagedRecords.length === 0"><td colspan="10" class="empty">暂无记录</td></tr></tbody></table></div>
      <footer v-if="!loading && !errorMessage" class="pagination"><span class="pagination__info">共 {{ total }} 条</span><button class="page-btn" type="button" :disabled="page <= 1" @click="changePage(page - 1)"><span class="material-icons-outlined">chevron_left</span></button><button v-for="pageNumber in pageNumbers" :key="pageNumber" class="page-btn" :class="{ active: pageNumber === page }" type="button" @click="changePage(pageNumber)">{{ pageNumber }}</button><button class="page-btn" type="button" :disabled="page >= totalPages" @click="changePage(page + 1)"><span class="material-icons-outlined">chevron_right</span></button></footer>
    </section>
    <div v-if="selectedRecord" class="detail-mask" role="presentation" @click.self="closeDetails">
      <section class="detail-modal" role="dialog" aria-modal="true" :aria-label="`${selectedRecord.plate || '车辆'}通行详情`">
        <header class="detail-modal__head"><div><span class="detail-kicker">通行记录</span><h2>{{ selectedRecord.plate || "无牌车辆" }}</h2></div><button class="icon-button" type="button" aria-label="关闭详情" @click="closeDetails"><span class="material-icons-outlined">close</span></button></header>
        <div class="detail-modal__body">
          <div class="detail-photo-panel">
            <div v-if="detailImageLoading" class="detail-photo-empty"><span class="material-icons-outlined detail-spinner">progress_activity</span><strong>正在加载抓拍图片</strong><span>请稍候</span></div>
            <div v-else-if="detailImageSrc && !detailImageError" class="detail-photo-frame"><img :src="detailImageSrc" :alt="`${selectedRecord.plate || '车辆'}抓拍图片`" @error="detailImageError = true"></div>
            <div v-else class="detail-photo-empty"><span class="material-icons-outlined">no_photography</span><strong>{{ selectedRecord.photo ? "图片暂时无法加载" : "暂无抓拍图片" }}</strong><span>{{ selectedRecord.photo ? "请稍后重试或联系管理员" : "该记录未返回图片地址" }}</span></div>
            <div class="detail-photo-caption"><span class="material-icons-outlined">photo_camera</span><span>进出场抓拍</span></div>
          </div>
          <div class="detail-info-panel">
            <div class="detail-status-row"><span class="tag" :class="selectedRecord.direction === '进' ? 'tag--blue' : 'tag--gray'">{{ selectedRecord.direction }}场</span><span class="tag" :class="passClass(selectedRecord.passType)">{{ selectedRecord.passType || "未知放行" }}</span><span v-if="selectedRecord.status" class="tag" :class="selectedRecord.status === '正常' ? 'tag--green' : 'tag--red'">{{ selectedRecord.status }}</span></div>
            <dl class="detail-grid"><div><dt>通行时间</dt><dd>{{ selectedRecord.time || "-" }}</dd></div><div><dt>进出场地点</dt><dd>{{ selectedRecord.gate || "-" }}</dd></div><div><dt>车主名称</dt><dd>{{ selectedRecord.owner || "-" }}</dd></div><div><dt>所属部门</dt><dd>{{ selectedRecord.dept || "-" }}</dd></div><div><dt>车辆类型</dt><dd>{{ selectedRecord.vehicleType || "-" }}</dd></div><div><dt>记录编号</dt><dd>{{ selectedRecord.id }}</dd></div><div class="detail-grid__wide"><dt>记录状态</dt><dd>{{ selectedRecord.status || "-" }}</dd></div></dl>
          </div>
        </div>
        <footer class="detail-modal__foot"><button class="button button--ghost" type="button" @click="closeDetails"><span class="material-icons-outlined">close</span>关闭</button></footer>
      </section>
    </div>
  </section>
</template>

<script setup lang="ts">
interface VehicleRecord { id: number; plate?: string | null; owner?: string | null; dept?: string | null; time: string; direction: string; gate?: string | null; method?: string | null; status?: string | null; photo?: string | null; vehicleType?: string | null; passDesc?: string | null }
interface RecordList { items: VehicleRecord[]; total: number }
const http = useHttp(); const pageSize = 8; const records = ref<VehicleRecord[]>([]); const total = ref(0); const loading = ref(true); const errorMessage = ref(""); const page = ref(1); const filters = reactive({ keyword: "", direction: "", gate: "", passType: "" });
const normalizedRecords = computed(() => records.value.map((record) => ({ ...record, passType: record.method || "未知", passDesc: record.status || "" })));
const gates = computed(() => [...new Set(normalizedRecords.value.map((record) => record.gate).filter((gate): gate is string => Boolean(gate)))]); const passTypes = computed(() => [...new Set(normalizedRecords.value.map((record) => record.passType).filter(Boolean))]);
const filteredRecords = computed(() => { const keyword = filters.keyword.toLowerCase(); return normalizedRecords.value.filter((record) => (!keyword || `${record.plate || ""}${record.owner || ""}${record.dept || ""}`.toLowerCase().includes(keyword)) && (!filters.direction || record.direction === filters.direction) && (!filters.gate || record.gate === filters.gate) && (!filters.passType || record.passType === filters.passType)); });
const totalPages = computed(() => Math.max(1, Math.ceil(total.value / pageSize))); const pageNumbers = computed(() => Array.from({ length: totalPages.value }, (_, index) => index + 1).slice(Math.max(0, page.value - 3), page.value + 2)); const pagedRecords = computed(() => filteredRecords.value);
const selectedRecord = ref<VehicleRecord | null>(null); const detailImageSrc = ref(""); const detailImageError = ref(false); const detailImageLoading = ref(false); const authToken = useCookie<string | null>("cartask_auth_token", { sameSite: "lax", path: "/" });
function normalizedAuthorization(token?: string | null) { const value = token?.trim(); return value ? (/^bearer\s+/i.test(value) ? value : `Bearer ${value}`) : ""; }
function isProtectedFileUrl(url: string) { try { return new URL(url, window.location.origin).pathname.includes("/api/files/"); } catch { return url.includes("/api/files/"); } }
async function loadDetailImage(url: string) { detailImageLoading.value = true; detailImageError.value = false; try { if (!isProtectedFileUrl(url)) { detailImageSrc.value = url; return; } const response = await fetch(url, { headers: { Authorization: normalizedAuthorization(authToken.value) } }); if (!response.ok) throw new Error(`image request failed: ${response.status}`); const blob = await response.blob(); detailImageSrc.value = URL.createObjectURL(blob); } catch { detailImageSrc.value = ""; detailImageError.value = true; } finally { detailImageLoading.value = false; } }
function releaseDetailImage() { if (detailImageSrc.value.startsWith("blob:")) URL.revokeObjectURL(detailImageSrc.value); detailImageSrc.value = ""; }
function openDetails(record: VehicleRecord) { releaseDetailImage(); selectedRecord.value = record; detailImageError.value = false; if (record.photo) void loadDetailImage(record.photo); }
function closeDetails() { releaseDetailImage(); selectedRecord.value = null; detailImageError.value = false; detailImageLoading.value = false; }
function handleDetailsKeydown(event: KeyboardEvent) { if (event.key === "Escape" && selectedRecord.value) closeDetails(); }
function passClass(passType?: string) { return passType === "车牌识别" || passType === "自动放行" ? "tag--green" : passType === "刷卡" || passType === "手动放行" ? "tag--blue" : "tag--red"; } function search() { page.value = 1; void loadRecords(); } function resetFilters() { Object.assign(filters, { keyword: "", direction: "", gate: "", passType: "" }); page.value = 1; void loadRecords(); } function changePage(nextPage: number) { page.value = Math.min(Math.max(1, nextPage), totalPages.value); void loadRecords(); }
async function loadRecords() { loading.value = true; errorMessage.value = ""; try { const result = await http.get<RecordList>("/vehicle-records", { keyword: filters.keyword || undefined, direction: filters.direction || undefined, gate: filters.gate || undefined, passType: filters.passType || undefined, page: page.value, pageSize }); records.value = result.items || []; total.value = result.total || 0; } catch (error) { errorMessage.value = (error as { statusMessage?: string }).statusMessage || "车辆进出记录加载失败"; } finally { loading.value = false; } }
function exportRecords() { const rows = [["车牌号码", "车主名称", "方向", "进出时间", "进出场地点", "车辆类型", "放行类型", "记录状态"], ...filteredRecords.value.map((record) => [record.plate || "", record.owner || "", record.direction, record.time, record.gate || "", record.vehicleType || "", record.passType || "", record.status || ""])]; const csv = rows.map((row) => row.map((cell) => `"${String(cell).replaceAll('"', '""')}"`).join(",")).join("\r\n"); const link = document.createElement("a"); link.href = URL.createObjectURL(new Blob(["\ufeff" + csv], { type: "text/csv;charset=utf-8" })); link.download = "车辆进出记录.csv"; link.click(); URL.revokeObjectURL(link.href); }
watch(filteredRecords, () => { if (page.value > totalPages.value) page.value = totalPages.value; }); onMounted(() => { loadRecords(); window.addEventListener("keydown", handleDetailsKeydown); }); onBeforeUnmount(() => { window.removeEventListener("keydown", handleDetailsKeydown); releaseDetailImage(); });
</script>

<style scoped>
