ne-flex;height:44px;justify-content:center;width:64px}.record-photo--in{background:#eff6ff;color:var(--primary)}.record-photo--out{background:#f4f4f5;color:var(--text-sub)}.plate{font-size:13px;font-weight:600;letter-spacing:.5px}.text-sub{color:var(--text-sub)!important}.nowrap{white-space:nowrap}.remark-cell{max-width:200px;overflow:hidden;text-overflow:ellipsis}.actions-cell{text-align:right!important}.detail-action{align-items:center;background:transparent;border:1px solid var(--border-strong);border-radius:5px;color:var(--primary);cursor:pointer;display:inline-flex;font:inherit;font-size:12px;gap:4px;height:30px;padding:0 9px}.detail-action:hover{background:var(--primary-soft)}.detail-action .material-icons-outlined{font-size:16px}.tag{align-items:center;border-radius:4px;display:inline-flex;font-size:12px;gap:4px;line-height:1.5;padding:2px 8px}.tag:before{background:currentColor;border-radius:50%;content:"";height:5px;width:5px}.tag--green{background:#ecfdf5;color:#059669}.tag--red{background:#fef2f2;color:#dc2626}.tag--blue{background:var(--primary-soft);color:var(--primary)}.tag--gray{background:#f4f4f5;color:var(--text-sub)}.state,.empty{color:var(--text-mute);padding:40px;text-align:center}.state--error{color:var(--red)}.pagination{align-items:center;border-top:1px solid var(--border);display:flex;flex-wrap:wrap;gap:4px;justify-content:flex-end;padding:12px 16px}.pagination__info{color:var(--text-sub);font-size:12px;margin-right:auto}.page-btn{align-items:center;background:var(--card);border:1px solid var(--border-strong);border-radius:5px;color:var(--text-sub);cursor:pointer;display:flex;font-size:12px;height:28px;justify-content:center;min-width:28px;padding:0 6px}.page-btn.active{background:var(--primary);border-color:var(--primary);color:#fff}.page-btn:disabled{cursor:not-allowed;opacity:.4}.page-btn .material-icons-outlined{font-size:16px}.detail-mask{align-items:center;background:rgb(15 23 42 / 46%);display:flex;inset:0;justify-content:center;padding:20px;position:fixed;z-index:400}.detail-modal{background:var(--card);border:1px solid var(--border-strong);border-radius:8px;box-shadow:0 20px 60px rgb(15 23 42 / 26%);max-width:820px;overflow:hidden;width:100%}.detail-modal__head{align-items:center;border-bottom:1px solid var(--border);display:flex;justify-content:space-between;padding:18px 22px}.detail-modal__head h2{color:var(--text);font-size:20px;font-weight:650;margin:2px 0 0}.detail-kicker{color:var(--text-mute);font-size:11px;font-weight:600;letter-spacing:.1em;text-transform:uppercase}.icon-button{align-items:center;background:transparent;border:1px solid transparent;border-radius:5px;color:var(--text-sub);cursor:pointer;display:inline-flex;height:32px;justify-content:center;width:32px}.icon-button:hover{background:var(--bg);color:var(--text)}.icon-button .material-icons-outlined{font-size:20px}.detail-modal__body{display:grid;gap:24px;grid-template-columns:minmax(260px,1.05fr) minmax(260px,1fr);padding:22px}.detail-photo-panel{min-width:0}.detail-photo-frame{background:#0f172a;border-radius:6px;display:flex;min-height:280px;overflow:hidden}.detail-photo-frame img{height:100%;max-height:420px;object-fit:contain;width:100%}.detail-photo-empty{align-items:center;background:var(--bg);border:1px dashed var(--border-strong);border-radius:6px;color:var(--text-mute);display:flex;flex-direction:column;gap:7px;justify-content:center;min-height:280px;padding:24px;text-align:center}.detail-photo-empty .material-icons-outlined{font-size:40px}.detail-photo-empty strong{color:var(--text-sub);font-size:13px}.detail-photo-empty span:last-child{font-size:11px}.detail-spinner{animation:detail-spin 1.1s linear infinite}.detail-photo-caption{align-items:center;color:var(--text-mute);display:flex;font-size:11px;gap:5px;margin-top:9px}.detail-photo-caption .material-icons-outlined{font-size:15px}.detail-info-panel{min-width:0}.detail-status-row{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:18px}.detail-grid{display:grid;gap:0 18px;grid-template-columns:repeat(2,minmax(0,1fr));margin:0}.detail-grid>div{border-bottom:1px solid var(--border);padding:12px 0}.detail-grid__wide{grid-column:1 / -1}.detail-grid dt{color:var(--text-mute);font-size:11px;margin-bottom:5px}.detail-grid dd{color:var(--text);font-size:13px;line-height:1.5;margin:0;overflow-wrap:anywhere}.detail-modal__foot{border-top:1px solid var(--border);display:flex;justify-content:flex-end;padding:12px 22px}@keyframes detail-spin{to{transform:rotate(360deg)}}@media(max-width:768px){.page{padding:16px}.toolbar__right{margin-left:0}.toolbar .input,.toolbar .select,.toolbar__right{width:100%}.toolbar__right .button{flex:1}.detail-mask{padding:12px}.detail-modal__body{grid-template-columns:1fr;padding:16px}.detail-photo-frame,.detail-photo-empty{min-height:220px}.detail-modal__head,.detail-modal__foot{padding-left:16px;padding-right:16px}}
</style>
